const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  Header, Footer, AlignmentType, LevelFormat, TabStopType, TabStopPosition,
  TableOfContents, HeadingLevel, BorderStyle, WidthType, ShadingType,
  VerticalAlign, PageNumber, PageBreak
} = require("docx");
const { SOPS, KPI_REFERENCE } = require("./sops.js");

// ---- Brand palette ----
const PLUM = "6B4A5E";      // primary heading
const PLUMDK = "4A3340";    // deep plum
const GOLD = "A8865F";      // champagne accent
const GOLDDK = "8A6B45";
const CHARCOAL = "2E2A2D";  // body
const GREY = "6B656A";      // muted
const BLUSH = "F7F1F3";     // light fill
const BLUSHDK = "ECDEE3";   // header-row fill
const BORDER = "DBC9D0";    // soft border
const WHITE = "FFFFFF";

const CONTENT_W = 9360; // US Letter, 1" margins

// ---- helpers ----
const FT = (text, opts = {}) => new TextRun({ text, ...opts });

function goldRule(space = 1, size = 14, color = GOLD) {
  return new Paragraph({
    border: { bottom: { style: BorderStyle.SINGLE, size, color, space } },
    spacing: { after: 120 },
    children: [FT("")]
  });
}

function body(text, opts = {}) {
  return new Paragraph({
    spacing: { after: opts.after ?? 140, line: 276 },
    alignment: opts.align,
    children: [FT(text, { color: CHARCOAL, size: 21, ...opts.run })]
  });
}

function bullet(text, ref = "bullets") {
  return new Paragraph({
    numbering: { reference: ref, level: 0 },
    spacing: { after: 80, line: 264 },
    children: [FT(text, { color: CHARCOAL, size: 21 })]
  });
}

function numbered(text, ref) {
  return new Paragraph({
    numbering: { reference: ref, level: 0 },
    spacing: { after: 100, line: 268 },
    children: [FT(text, { color: CHARCOAL, size: 21 })]
  });
}

// subsection label (gold, small caps style)
function label(text) {
  return new Paragraph({
    spacing: { before: 200, after: 90 },
    children: [FT(text.toUpperCase(), { color: GOLDDK, size: 19, bold: true, characterSpacing: 30 })]
  });
}

// shaded script / callout box (single-cell table)
function calloutBox(titleText, lines, fill = BLUSH, accent = GOLD) {
  const kids = [];
  if (titleText) {
    kids.push(new Paragraph({
      spacing: { after: 60 },
      children: [FT(titleText.toUpperCase(), { color: accent === GOLD ? GOLDDK : accent, size: 17, bold: true, characterSpacing: 24 })]
    }));
  }
  lines.forEach((ln, i) => {
    kids.push(new Paragraph({
      spacing: { after: i === lines.length - 1 ? 0 : 80, line: 268 },
      children: [FT(ln, { color: CHARCOAL, size: 21, italics: true })]
    }));
  });
  return new Table({
    width: { size: CONTENT_W, type: WidthType.DXA },
    columnWidths: [CONTENT_W],
    borders: {
      top: { style: BorderStyle.SINGLE, size: 2, color: fill },
      bottom: { style: BorderStyle.SINGLE, size: 2, color: fill },
      right: { style: BorderStyle.SINGLE, size: 2, color: fill },
      left: { style: BorderStyle.SINGLE, size: 24, color: accent }
    },
    rows: [new TableRow({
      children: [new TableCell({
        width: { size: CONTENT_W, type: WidthType.DXA },
        shading: { fill, type: ShadingType.CLEAR },
        margins: { top: 160, bottom: 160, left: 220, right: 220 },
        children: kids
      })]
    })]
  });
}

// metric table ("What good looks like")
function metricTable(rows, headLeft = "Metric", headRight = "Target") {
  const c1 = 5760, c2 = CONTENT_W - c1;
  const cellBorder = { style: BorderStyle.SINGLE, size: 1, color: BORDER };
  const borders = { top: cellBorder, bottom: cellBorder, left: cellBorder, right: cellBorder };
  const head = new TableRow({
    tableHeader: true,
    children: [
      new TableCell({
        width: { size: c1, type: WidthType.DXA }, borders,
        shading: { fill: PLUM, type: ShadingType.CLEAR },
        margins: { top: 90, bottom: 90, left: 140, right: 140 },
        children: [new Paragraph({ children: [FT(headLeft.toUpperCase(), { color: WHITE, size: 18, bold: true, characterSpacing: 20 })] })]
      }),
      new TableCell({
        width: { size: c2, type: WidthType.DXA }, borders,
        shading: { fill: PLUM, type: ShadingType.CLEAR },
        margins: { top: 90, bottom: 90, left: 140, right: 140 },
        children: [new Paragraph({ children: [FT(headRight.toUpperCase(), { color: WHITE, size: 18, bold: true, characterSpacing: 20 })] })]
      })
    ]
  });
  const dataRows = rows.map((r, i) => new TableRow({
    children: [
      new TableCell({
        width: { size: c1, type: WidthType.DXA }, borders,
        shading: { fill: i % 2 ? WHITE : BLUSH, type: ShadingType.CLEAR },
        margins: { top: 80, bottom: 80, left: 140, right: 140 },
        children: [new Paragraph({ children: [FT(r[0], { color: CHARCOAL, size: 20 })] })]
      }),
      new TableCell({
        width: { size: c2, type: WidthType.DXA }, borders,
        shading: { fill: i % 2 ? WHITE : BLUSH, type: ShadingType.CLEAR },
        margins: { top: 80, bottom: 80, left: 140, right: 140 },
        children: [new Paragraph({ children: [FT(r[1], { color: PLUMDK, size: 20, bold: true })] })]
      })
    ]
  }));
  return new Table({
    width: { size: CONTENT_W, type: WidthType.DXA },
    columnWidths: [c1, c2],
    rows: [head, ...dataRows]
  });
}

// three-column KPI table
function kpiTable(rows) {
  const c1 = 2900, c2 = 3700, c3 = CONTENT_W - c1 - c2;
  const cellBorder = { style: BorderStyle.SINGLE, size: 1, color: BORDER };
  const borders = { top: cellBorder, bottom: cellBorder, left: cellBorder, right: cellBorder };
  const head = new TableRow({
    tableHeader: true,
    children: [["KPI", c1], ["What it measures", c2], ["Target", c3]].map(([t, w]) =>
      new TableCell({
        width: { size: w, type: WidthType.DXA }, borders,
        shading: { fill: PLUM, type: ShadingType.CLEAR },
        margins: { top: 90, bottom: 90, left: 130, right: 130 },
        children: [new Paragraph({ children: [FT(t.toUpperCase(), { color: WHITE, size: 17, bold: true, characterSpacing: 16 })] })]
      })
    )
  });
  const data = rows.map((r, i) => new TableRow({
    children: r.map((val, j) => new TableCell({
      width: { size: [c1, c2, c3][j], type: WidthType.DXA }, borders,
      shading: { fill: i % 2 ? WHITE : BLUSH, type: ShadingType.CLEAR },
      margins: { top: 80, bottom: 80, left: 130, right: 130 },
      children: [new Paragraph({ children: [FT(val, { color: j === 2 ? PLUMDK : CHARCOAL, size: 19, bold: j === 0 || j === 2 })] })]
    }))
  }));
  return new Table({ width: { size: CONTENT_W, type: WidthType.DXA }, columnWidths: [c1, c2, c3], rows: [head, ...data] });
}

// ---- Document assembly ----
const children = [];

// ===== COVER =====
children.push(new Paragraph({ spacing: { before: 2600, after: 0 }, alignment: AlignmentType.CENTER,
  children: [FT("THE LUXORA COLLECTIVE", { color: GOLDDK, size: 22, bold: true, characterSpacing: 80 })] }));
children.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 60, after: 360 },
  children: [FT("PLAYBOOK SERIES", { color: GREY, size: 17, characterSpacing: 60 })] }));

children.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 200, after: 0 },
  children: [FT("The 10 Must-Have SOPs", { color: PLUM, size: 64, bold: true, font: "Georgia" })] }));
children.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 60, after: 280 },
  children: [FT("for Independent Med Spa Owners", { color: PLUMDK, size: 34, font: "Georgia", italics: true })] }));

children.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 60 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 12, color: GOLD, space: 8 } }, children: [FT("")] }));

children.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 220, after: 0 },
  children: [FT("The systems that turn a busy practice into a profitable,", { color: CHARCOAL, size: 22, italics: true })] }));
children.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 0 },
  children: [FT("predictable business that runs without the owner in every transaction.", { color: CHARCOAL, size: 22, italics: true })] }));

children.push(new Paragraph({ spacing: { before: 3000, after: 0 }, alignment: AlignmentType.CENTER,
  children: [FT("A done-with-you deliverable", { color: GREY, size: 18 })] }));
children.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 30 },
  children: [FT("theluxoracollective.co", { color: GOLDDK, size: 19, bold: true })] }));

children.push(new Paragraph({ children: [new PageBreak()] }));

// ===== LETTER =====
children.push(new Paragraph({ heading: HeadingLevel.HEADING_1, children: [FT("A Note Before You Begin")] }));
children.push(goldRule());
[
  "You did not open a med spa to live inside spreadsheets, chase no-shows, or be the only person who knows how anything gets done. You opened it to deliver transformation, to give women a place where they feel cared for and leave feeling more like themselves. Somewhere along the way, the operations of running it started to compete with the reason you started it.",
  "This playbook is the fix. It contains the ten standard operating procedures that, in our experience, separate the practices that quietly plateau from the ones that grow with calm and confidence. None of them require new technology you do not have, and none of them require you to become a different kind of leader. They simply take the things you already do well, sometimes, and make them happen reliably, every time, no matter who is on shift.",
  "This is the heart of how Luxora works: we build from the inside out. Before recommending a single new investment, we find and seal the places revenue quietly leaks, undertrained front desks, unconverted consultations, clients who drift away, missing memberships, and weak package structures. The SOPs in this playbook map directly onto those leaks. Install them, and the same number of leads and the same marketing spend will produce noticeably more revenue.",
  "Read it once cover to cover. Then implement it the way we recommend at the end: one SOP at a time, in order, until each is simply how things are done. You will not just have better systems. You will have a business that is more capable, more valuable, and far less dependent on you for every decision."
].forEach(p => children.push(body(p)));
children.push(new Paragraph({ spacing: { before: 160 }, children: [FT("With you in it,", { color: CHARCOAL, size: 21, italics: true })] }));
children.push(new Paragraph({ spacing: { before: 40 }, children: [FT("Bethany", { color: PLUM, size: 26, bold: true, font: "Georgia" })] }));
children.push(new Paragraph({ children: [FT("Co-Founder & CEO, The Luxora Collective", { color: GREY, size: 19 })] }));

children.push(new Paragraph({ children: [new PageBreak()] }));

// ===== HOW TO USE =====
children.push(new Paragraph({ heading: HeadingLevel.HEADING_1, children: [FT("How to Use This Playbook")] }));
children.push(goldRule());
children.push(body("Every SOP in this playbook follows the same structure, so your team always knows where to look. Each one answers the same questions:"));
[
  "Why This Matters: the revenue or experience reason the SOP exists, so it is never treated as busywork.",
  "Who Owns It: the single person accountable for the standard, even when others carry it out.",
  "When It Runs: the trigger that should set the procedure in motion every time.",
  "The Procedure: the step-by-step sequence, written so a new hire could follow it.",
  "Scripts and Language: the exact words to use at the moments that matter most.",
  "Tools You Need: the systems that make the SOP effortless to run.",
  "What Good Looks Like: the targets that tell you whether the SOP is actually working.",
  "Common Mistakes: the traps to avoid, drawn from what we see most often."
].forEach(t => children.push(bullet(t)));
children.push(body("Customize the bracketed details to your practice, your services, and your voice. These SOPs are a proven starting point, not a straitjacket. The goal is consistency, not rigidity.", { after: 120 }));
children.push(calloutBox("The Luxora Standard", [
  "A good SOP is not the one with the most steps. It is the one your team will actually follow on the busiest day of the week. Keep them clear, keep them visible, and review them often. A system written down and never used is just paper."
], BLUSHDK, PLUM));

children.push(new Paragraph({ children: [new PageBreak()] }));

// ===== TOC =====
children.push(new Paragraph({ heading: HeadingLevel.HEADING_1, children: [FT("Contents")] }));
children.push(goldRule());
children.push(new TableOfContents("Contents", { hyperlink: true, headingStyleRange: "1-1" }));
children.push(new Paragraph({ spacing: { before: 200 }, children: [FT("THE TEN SOPS AT A GLANCE", { color: GOLDDK, size: 18, bold: true, characterSpacing: 24 })] }));
children.push(new Paragraph({ spacing: { after: 120 }, children: [FT("Each maps to a stage of the client journey and a place revenue commonly leaks.", { color: GREY, size: 19, italics: true })] }));
// glance table
(() => {
  const c1 = 900, c2 = 5400, c3 = CONTENT_W - c1 - c2;
  const cb = { style: BorderStyle.SINGLE, size: 1, color: BORDER };
  const borders = { top: cb, bottom: cb, left: cb, right: cb };
  const head = new TableRow({ tableHeader: true, children: [["No.", c1], ["SOP", c2], ["Pillar", c3]].map(([t, w]) =>
    new TableCell({ width: { size: w, type: WidthType.DXA }, borders, shading: { fill: PLUM, type: ShadingType.CLEAR },
      margins: { top: 80, bottom: 80, left: 120, right: 120 },
      children: [new Paragraph({ children: [FT(t.toUpperCase(), { color: WHITE, size: 17, bold: true, characterSpacing: 16 })] })] })) });
  const rows = SOPS.map((s, i) => new TableRow({ children: [
    new TableCell({ width: { size: c1, type: WidthType.DXA }, borders, shading: { fill: i % 2 ? WHITE : BLUSH, type: ShadingType.CLEAR },
      margins: { top: 70, bottom: 70, left: 120, right: 120 }, verticalAlign: VerticalAlign.CENTER,
      children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [FT(s.number, { color: GOLDDK, size: 22, bold: true, font: "Georgia" })] })] }),
    new TableCell({ width: { size: c2, type: WidthType.DXA }, borders, shading: { fill: i % 2 ? WHITE : BLUSH, type: ShadingType.CLEAR },
      margins: { top: 70, bottom: 70, left: 120, right: 120 },
      children: [new Paragraph({ children: [FT(s.title, { color: CHARCOAL, size: 20, bold: true })] })] }),
    new TableCell({ width: { size: c3, type: WidthType.DXA }, borders, shading: { fill: i % 2 ? WHITE : BLUSH, type: ShadingType.CLEAR },
      margins: { top: 70, bottom: 70, left: 120, right: 120 },
      children: [new Paragraph({ children: [FT(s.pillar, { color: PLUMDK, size: 19 })] })] })
  ] }));
  children.push(new Table({ width: { size: CONTENT_W, type: WidthType.DXA }, columnWidths: [c1, c2, c3], rows: [head, ...rows] }));
})();

children.push(new Paragraph({ children: [new PageBreak()] }));

// ===== SOP SECTIONS =====
SOPS.forEach((s, idx) => {
  // SOP divider header band
  children.push(new Paragraph({ spacing: { before: 200, after: 0 },
    children: [FT(`SOP ${s.number}`, { color: GOLDDK, size: 22, bold: true, characterSpacing: 40 })] }));
  children.push(new Paragraph({ heading: HeadingLevel.HEADING_1, spacing: { before: 40, after: 60 },
    children: [FT(s.title)] }));
  children.push(new Paragraph({ spacing: { after: 60 },
    children: [FT(s.tagline, { color: PLUMDK, size: 22, italics: true })] }));
  children.push(goldRule());

  // Why this matters
  children.push(label("Why This Matters"));
  s.why.forEach(p => children.push(body(p)));

  // Owner + trigger as a compact two-row table
  (() => {
    const c1 = 2400, c2 = CONTENT_W - c1;
    const cb = { style: BorderStyle.SINGLE, size: 1, color: BORDER };
    const borders = { top: cb, bottom: cb, left: cb, right: cb };
    const mkRow = (k, v) => new TableRow({ children: [
      new TableCell({ width: { size: c1, type: WidthType.DXA }, borders, shading: { fill: BLUSHDK, type: ShadingType.CLEAR },
        margins: { top: 70, bottom: 70, left: 140, right: 120 },
        children: [new Paragraph({ children: [FT(k.toUpperCase(), { color: PLUMDK, size: 17, bold: true, characterSpacing: 14 })] })] }),
      new TableCell({ width: { size: c2, type: WidthType.DXA }, borders, shading: { fill: WHITE, type: ShadingType.CLEAR },
        margins: { top: 70, bottom: 70, left: 140, right: 140 },
        children: [new Paragraph({ children: [FT(v, { color: CHARCOAL, size: 20 })] })] })
    ] });
    children.push(new Paragraph({ spacing: { before: 80, after: 60 }, children: [FT("")] }));
    children.push(new Table({ width: { size: CONTENT_W, type: WidthType.DXA }, columnWidths: [c1, c2],
      rows: [mkRow("SOP Owner", s.owner), mkRow("When It Runs", s.trigger)] }));
  })();

  // Procedure
  children.push(label("The Procedure"));
  const stepRef = `steps${idx}`;
  s.steps.forEach(st => children.push(numbered(st, stepRef)));

  // Scripts
  if (s.scripts && s.scripts.length) {
    children.push(label("Scripts and Language"));
    s.scripts.forEach((sc, j) => {
      children.push(calloutBox(sc.label, sc.lines));
      if (j !== s.scripts.length - 1) children.push(new Paragraph({ spacing: { after: 100 }, children: [FT("")] }));
    });
  }

  // Tools
  children.push(label("Tools You Need"));
  s.tools.forEach(t => children.push(bullet(t, `tools${idx}`)));

  // What good looks like
  children.push(label("What Good Looks Like"));
  children.push(metricTable(s.good));

  // Mistakes
  children.push(label("Common Mistakes to Avoid"));
  s.mistakes.forEach(m => children.push(bullet(m, `miss${idx}`)));

  children.push(new Paragraph({ children: [new PageBreak()] }));
});

// ===== IMPLEMENTATION ROADMAP =====
children.push(new Paragraph({ heading: HeadingLevel.HEADING_1, children: [FT("Your Implementation Roadmap")] }));
children.push(goldRule());
children.push(body("Do not try to install all ten SOPs at once. That is how good intentions die. Build them in sequence, give each one to two weeks to become a habit, and only move on once the current one is simply how things are done. This order follows the client journey and front-loads the SOPs that recover revenue fastest."));

const ROADMAP = [
  ["Weeks 1 to 2", "SOP 01 and 02", "Capture and convert what you are already paying to attract. Fix lead response and the front desk first, because they sit on top of the funnel and pay back immediately."],
  ["Weeks 3 to 4", "SOP 03", "Standardize the consultation. This is where the largest single revenue gain usually lives."],
  ["Weeks 5 to 6", "SOP 04 and 05", "Protect the new client and lock in consistent results, so retention has something to retain."],
  ["Weeks 7 to 8", "SOP 06 and 07", "Install recurring revenue and outcome-based packages, the engine of lifetime value."],
  ["Weeks 9 to 10", "SOP 08 and 09", "Mine the database and build reputation. The cheapest revenue and the strongest marketing you have."],
  ["Week 11 onward", "SOP 10", "Install the weekly KPI rhythm that holds every other SOP accountable and keeps you in control."]
];
(() => {
  const c1 = 1900, c2 = 1900, c3 = CONTENT_W - c1 - c2;
  const cb = { style: BorderStyle.SINGLE, size: 1, color: BORDER };
  const borders = { top: cb, bottom: cb, left: cb, right: cb };
  const head = new TableRow({ tableHeader: true, children: [["Timing", c1], ["Install", c2], ["Why now", c3]].map(([t, w]) =>
    new TableCell({ width: { size: w, type: WidthType.DXA }, borders, shading: { fill: PLUM, type: ShadingType.CLEAR },
      margins: { top: 90, bottom: 90, left: 130, right: 130 },
      children: [new Paragraph({ children: [FT(t.toUpperCase(), { color: WHITE, size: 17, bold: true, characterSpacing: 16 })] })] })) });
  const rows = ROADMAP.map((r, i) => new TableRow({ children: r.map((val, j) => new TableCell({
    width: { size: [c1, c2, c3][j], type: WidthType.DXA }, borders,
    shading: { fill: i % 2 ? WHITE : BLUSH, type: ShadingType.CLEAR },
    margins: { top: 80, bottom: 80, left: 130, right: 130 },
    children: [new Paragraph({ children: [FT(val, { color: j === 2 ? CHARCOAL : PLUMDK, size: 19, bold: j < 2 })] })] })) }));
  children.push(new Table({ width: { size: CONTENT_W, type: WidthType.DXA }, columnWidths: [c1, c2, c3], rows: [head, ...rows] }));
})();
children.push(new Paragraph({ spacing: { before: 160 }, children: [FT("")] }));
children.push(calloutBox("Knowledge Transfer Is the Point", [
  "Every SOP you install should make your team more capable, not more dependent on you. As you roll each one out, hand it off completely: train it, post it, assign the owner, and step back. The goal is a practice that runs beautifully whether or not you are in the building. That is what makes it both a better life for you and a more valuable business."
], BLUSHDK, PLUM));

children.push(new Paragraph({ children: [new PageBreak()] }));

// ===== KPI APPENDIX =====
children.push(new Paragraph({ heading: HeadingLevel.HEADING_1, children: [FT("Appendix: Your Core KPI Reference")] }));
children.push(goldRule());
children.push(body("These are the numbers that tell you whether the systems in this playbook are working. Track this focused set every week in your SOP 10 review. If a number drifts, the SOP that produces it is the place to look."));
children.push(kpiTable(KPI_REFERENCE));
children.push(new Paragraph({ spacing: { before: 200 }, children: [FT("")] }));
children.push(body("An optional Longevity and Wellness Stack is available as an add-on for practices expanding into peptides, hormone optimization, and wellness, and integrates with these same SOPs.", { run: { italics: true, color: GREY, size: 19 } }));

children.push(new Paragraph({ children: [new PageBreak()] }));

// ===== CLOSING / CTA =====
children.push(new Paragraph({ spacing: { before: 800 }, alignment: AlignmentType.CENTER,
  children: [FT("READY TO INSTALL THESE WITH A PARTNER?", { color: GOLDDK, size: 19, bold: true, characterSpacing: 30 })] }));
children.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 120, after: 0 },
  children: [FT("Start with a Revenue Leak Audit", { color: PLUM, size: 40, bold: true, font: "Georgia" })] }));
children.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 40, after: 60 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 10, color: GOLD, space: 8 } }, children: [FT("")] }));
[
  "This playbook shows you what to build. A Revenue Leak Audit shows you exactly where your practice is leaking revenue right now, and what it is worth to seal it.",
  "From there, the Luxora method is simple: we deliver your Market Blueprint, then we install your full Growth Engine with you, right services at the right time, staff sales training, memberships, package architecture, AI follow-up, CRM, partnerships, reputation, and marketing, with knowledge transfer at every step.",
  "Done with you, not done to you. So you finish more capable, more confident, and fully in control."
].forEach(p => children.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 140, line: 276 },
  children: [FT(p, { color: CHARCOAL, size: 21 })] })));
children.push(new Paragraph({ spacing: { before: 240 }, alignment: AlignmentType.CENTER,
  children: [FT("theluxoracollective.co", { color: PLUM, size: 26, bold: true })] }));
children.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 30 },
  children: [FT("The Luxora Collective  |  Playbook Series", { color: GREY, size: 18, characterSpacing: 20 })] }));

// ---- numbering configs ----
const numberingConfig = [
  { reference: "bullets", levels: [{ level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
    style: { run: { color: GOLD }, paragraph: { indent: { left: 460, hanging: 260 } } } }] }
];
SOPS.forEach((s, idx) => {
  numberingConfig.push({ reference: `steps${idx}`, levels: [{ level: 0, format: LevelFormat.DECIMAL, text: "%1.", alignment: AlignmentType.LEFT,
    style: { run: { color: GOLDDK, bold: true }, paragraph: { indent: { left: 460, hanging: 320 } } } }] });
  numberingConfig.push({ reference: `tools${idx}`, levels: [{ level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
    style: { run: { color: GOLD }, paragraph: { indent: { left: 460, hanging: 260 } } } }] });
  numberingConfig.push({ reference: `miss${idx}`, levels: [{ level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
    style: { run: { color: GOLD }, paragraph: { indent: { left: 460, hanging: 260 } } } }] });
});

// ---- header/footer ----
const header = new Header({ children: [new Paragraph({
  tabStops: [{ type: TabStopType.RIGHT, position: 9360 }],
